// atlas -> n8n (ADR-040/041). One body shape: kind, title, severity, key, entity, opened_at,
// resolved_at, evidence[], summary{}, link. Builds a subject, an HTML email and a text fallback.
const b = $json.body || {};
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const resolved = b.kind === 'incident.resolved';
const color = resolved ? '#16a34a' : ({ warning: '#dc2626', notice: '#d97706', info: '#2563eb' }[b.severity] || '#6366f1');
const label = {
  'incident.opened': 'Incident', 'incident.reminder': 'Still open', 'incident.resolved': 'Resolved',
  'changes.digest': 'Changes', 'summary.daily': 'Daily summary', 'diagnostic.requested': 'Diagnosis',
  test: 'Test',
}[b.kind] || 'atlas';
const icon = resolved ? '✅' : ({ warning: '🔴', notice: '🟠', info: '🔵' }[b.severity] || '🔵');
const subject = `${icon} [atlas] ${b.title || label}`;

const rows = [];
if (b.summary && Object.keys(b.summary).length) {
  const cells = Object.entries(b.summary).map(([k, v]) =>
    `<td style="padding:10px 14px;text-align:center;border:1px solid #e5e7eb;border-radius:8px">` +
    `<div style="font-size:20px;font-weight:700;color:#111827">${esc(v)}</div>` +
    `<div style="font-size:11px;color:#6b7280;text-transform:uppercase;letter-spacing:.05em">${esc(k.replace(/_/g, ' '))}</div></td>`);
  rows.push(`<table role="presentation" cellspacing="6" style="margin:12px 0"><tr>${cells.join('')}</tr></table>`);
}
const ev = (b.evidence || []).slice(0, 20);
if (ev.length) {
  rows.push('<ul style="margin:12px 0;padding-left:18px;color:#374151;font-size:14px;line-height:1.5">' +
    ev.map((e) => `<li style="margin:3px 0">${esc(e)}</li>`).join('') + '</ul>');
}
const when = [b.opened_at ? `since ${esc(b.opened_at.slice(0, 16).replace('T', ' '))} UTC` : '',
              b.resolved_at ? `resolved ${esc(b.resolved_at.slice(0, 16).replace('T', ' '))} UTC` : '']
  .filter(Boolean).join(' · ');
const button = b.link
  ? `<p style="margin:18px 0 6px"><a href="${esc(b.link)}" style="background:${color};color:#fff;text-decoration:none;padding:10px 16px;border-radius:8px;font-weight:600;display:inline-block">Open in atlas</a></p>`
  : '';
const html = `<!doctype html><html><body style="margin:0;background:#f3f4f6;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:24px 12px">
<table role="presentation" width="100%" style="max-width:620px;background:#ffffff;border-radius:14px;overflow:hidden;border:1px solid #e5e7eb">
<tr><td style="height:6px;background:${color}"></td></tr>
<tr><td style="padding:20px 24px">
<div style="font-size:12px;font-weight:700;color:${color};text-transform:uppercase;letter-spacing:.08em">${esc(label)}</div>
<h1 style="margin:6px 0 4px;font-size:20px;line-height:1.3;color:#111827">${esc(b.title || 'atlas')}</h1>
${when ? `<div style="font-size:13px;color:#6b7280">${when}</div>` : ''}
${rows.join('\n')}
${button}
</td></tr>
<tr><td style="padding:12px 24px;background:#f9fafb;font-size:12px;color:#9ca3af">atlas · read-only homelab documentation${b.key ? ' · ' + esc(b.key) : ''}</td></tr>
</table></td></tr></table></body></html>`;

const text = [`${icon} ${b.title || label}`, when,
  ...Object.entries(b.summary || {}).map(([k, v]) => `• ${k.replace(/_/g, ' ')}: ${v}`),
  ...ev.map((e) => `– ${e}`), b.link ? `Open in atlas: ${b.link}` : ''].filter(Boolean).join('\n');

return { json: { kind: b.kind, severity: b.severity, key: b.key, subject, html, text } };
